const b = $input.first().json.body || {};
const clean = (v, d) => String(v || d).trim();
const topic = String(b.topic || '').trim();

return [{
  json: {
    valid: topic.length > 0 && topic.length <= 300,
    error: topic.length === 0 ? 'Topic is required'
         : topic.length > 300 ? 'Topic is too long (max 300 characters)' : '',
    topic,
    platform: clean(b.platform, 'Telegram'),
    contentType: clean(b.contentType, 'Educational'),
    tone: clean(b.tone, 'Professional'),
    targetAudience: clean(b.targetAudience, 'General audience'),
    length: clean(b.length, 'Medium'),
    keywords: clean(b.keywords, 'none'),
    attempt: 0,
    feedback: '',
  },
}];

const d = $input.first().json;

const platformRules = {
  Telegram: 'Telegram channel post. Plain text only, no markdown. Short paragraphs. Emojis allowed sparingly.',
  Discord: 'Discord community announcement. Plain text. Conversational, friendly community feel.',
}[d.platform] || 'General social media post.';

const lengthGuide = {
  Short: 'about 300 characters',
  Medium: 'about 600 characters',
  Long: 'about 900 characters',
}[d.length] || 'about 600 characters';

const retry = d.feedback
  ? `\n\nA previous draft was reviewed. Fix these problems in the new version:\n${d.feedback}`
  : '';

const prompt = `You are an expert social media content strategist.

Create high-quality social media content using the following information.

Topic: ${d.topic}
Platform: ${d.platform} (${platformRules})
Content Type: ${d.contentType}
Tone: ${d.tone}
Target Audience: ${d.targetAudience}
Length: ${lengthGuide}
Keywords: ${d.keywords}

Requirements:
1. Create an engaging opening hook.
2. Provide useful information.
3. Keep the language natural and readable.
4. Match the requested tone.
5. Match the target platform.
6. Avoid unsupported claims.
7. Do not invent statistics.
8. Avoid repetitive phrases.
9. Include relevant hashtags.
10. Include a suitable call-to-action where appropriate.
11. Return JSON only.${retry}

Return exactly this JSON shape:
{"title": "", "hook": "", "content": "", "hashtags": [], "callToAction": ""}`;

return [{ json: { ...d, prompt } }];

