const prev = $('Build prompt').first(0, $runIndex).json;
const raw = $input.first().json.choices?.[0]?.message?.content || '';

let draft;
try {
  draft = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, '').trim());
} catch (e) {
  throw new Error('Groq returned invalid JSON');
}

for (const k of ['title', 'hook', 'content', 'hashtags', 'callToAction']) {
  if (draft[k] === undefined) throw new Error('Draft is missing field: ' + k);
}
if (!Array.isArray(draft.hashtags)) throw new Error('hashtags must be an array');
if (!String(draft.content).trim()) throw new Error('Draft content is empty');

const reviewPrompt = `You are a strict social media content reviewer.
Evaluate this ${prev.platform} post about "${prev.topic}" (tone: ${prev.tone}, audience: ${prev.targetAudience}).

Post:
${JSON.stringify(draft)}

Check: grammar, clarity, relevance, engagement, tone, platform suitability, hashtags, repetition, unsupported claims, length.
Scores are 0 to 100. Be honest and critical; do not inflate scores.

Return exactly this JSON shape:
{"score": 0, "grammarScore": 0, "clarityScore": 0, "engagementScore": 0, "relevanceScore": 0, "issues": [], "suggestions": []}`;

return [{ json: { ...prev, draft, reviewPrompt } }];

