const prev = $('Parse draft').first(0, $runIndex).json;
const raw = $input.first().json.choices?.[0]?.message?.content || '';

let r;
try {
  r = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, '').trim());
} catch (e) {
  throw new Error('Review returned invalid JSON');
}

const num = (v) => Math.max(0, Math.min(100, Math.round(Number(v) || 0)));

const review = {
  score: num(r.score),
  grammarScore: num(r.grammarScore),
  clarityScore: num(r.clarityScore),
  engagementScore: num(r.engagementScore),
  relevanceScore: num(r.relevanceScore),
  issues: Array.isArray(r.issues) ? r.issues : [],
  suggestions: Array.isArray(r.suggestions) ? r.suggestions : [],
};

const attempt = $runIndex;
const passed = review.score >= 80;
const done = passed || attempt >= 2;

return [{ json: { ...prev, attempt, review, passed, done } }];

const d = $input.first().json;

return [{
  json: {
    topic: d.topic,
    platform: d.platform,
    contentType: d.contentType,
    tone: d.tone,
    targetAudience: d.targetAudience,
    length: d.length,
    keywords: d.keywords,
    feedback: [...d.review.issues, ...d.review.suggestions].join('\n'),
  },
}];
